import {useRef, useEffect, useState, useCallback} from 'react'
import {DatePicker, type SingleDatePickerProps} from '@github-ui/date-picker'

interface WrapperProps extends Omit<SingleDatePickerProps, 'value' | 'onChange'> {
  initialValue?: number | null
  name: string
  hiddenInputId?: string
  onMillisChange?: (ms: number | null) => void
}

export type DatePickerPartialProps = WrapperProps

export default function DatePickerField({
  initialValue,
  name,
  hiddenInputId = 'discussion_due_date',
  onMillisChange,
  ...pickerProps
}: DatePickerPartialProps) {
  const [selected, setSelected] = useState<Date | null>(() =>
    typeof initialValue === 'number' ? new Date(initialValue) : null,
  )

  const hiddenRef = useRef<HTMLInputElement>(null)

  const handleChange = useCallback(
    (date: Date | null) => {
      setSelected(date)

      const ms = date ? date.getTime() : null
      if (hiddenRef.current) {
        hiddenRef.current.value = ms !== null ? String(ms) : ''
        hiddenRef.current.dispatchEvent(new Event('input', {bubbles: true}))
      }
      onMillisChange?.(ms)
    },
    [onMillisChange],
  )

  useEffect(() => {
    if (hiddenRef.current) {
      hiddenRef.current.value = typeof initialValue === 'number' ? String(initialValue) : ''
    }
  }, [initialValue])

  const hiddenValue = selected ? String(selected.getTime()) : ''

  return (
    <>
      <input
        ref={hiddenRef}
        type="hidden"
        className="js-discussion-due-date"
        id={hiddenInputId}
        name={name}
        value={hiddenValue}
        readOnly
      />
      <DatePicker value={selected} onChange={handleChange} {...pickerProps} />
    </>
  )
}

try{ DatePickerField.displayName ||= 'DatePickerField' } catch {}